# whether the base may drive to help an arm reach (whole-body control). A plan
# built in the Plan Builder says where the robot stands, with its Navigate steps.
BASE_MAY_DRIVE_WHILE_REACHING = False

# objects placed in the Plan Builder: (mesh, x, y, z, roll, pitch, yaw, (r, g, b))
OBJECTS = [
]


@dataclass(kw_only=True)
class MyDemoDemonstration(RobotDemonstration):
    """A demonstration composed in the cramera Plan Builder."""

    def build_simulated_world(self) -> World:
        """Build the selected environment with its annotated robot.

        :return: The assembled semantic world.
        """
        return ROBOT_SCENE.build_world(os.path.join(_WORLDS, ENV_FILE))

    def is_scene_populated(self, world: World) -> bool:
        """Check whether every authored object exists in the world.

        :param world: World inspected for the authored objects.
        :return: Whether the scene already contains the complete object set.
        """
        return bool(OBJECTS) and all(len(world.get_bodies_by_name(spec[0])) == 1 for spec in OBJECTS)

    def populate_scene(self, world: World) -> None:
        """Spawn the authored objects at their saved poses.

        :param world: World receiving the movable object bodies.
        """
        # each object is free to move (Connection6DoF), so the robot can transport it
        for mesh, x, y, z, roll, pitch, yaw, rgb in OBJECTS:
            BodySpecification.mesh(
                mesh,
                os.path.join(_OBJECTS, mesh),
                color=Color(*rgb),
                parent_T_self=HomogeneousTransformationMatrix.from_xyz_rpy(
                    x, y, z, roll=roll, pitch=pitch, yaw=yaw),
                connection_specification=Connection6DoFSpecification(),
            ).spawn(world)

    def build_context(self, world: World) -> Context:
        """Reason about a simulated world and configure robot execution.

        :param world: Semantic world used for planning and execution.
        :return: Context for the selected robot.
        """
        if self.execution_type is not ExecutionType.REAL:
            with world.modify_world():
                WorldReasoner(world).reason()
                PlacementAnnotations(world, os.path.join(_WORLDS, ENV_FILE)).apply()
        robot = ROBOT_SCENE.selected_robot(world)
        if isinstance(robot, HasMobileBase):
            robot.mobile_base.full_body_controlled = BASE_MAY_DRIVE_WHILE_REACHING
        context = Context(
            world=world,
            robot=robot,
            _debug=False,
            ros_node=self.ros_node,
            alternative_motion_mappings=self.alternative_motion_mappings,
        )
        context.evaluate_conditions = False
        return context

    def build_plan(self, context: Context) -> Plan:
        """Compose the authored action sequence against the current world.

        :param context: Robot and world used to resolve the actions.
        :return: Executable plan containing the authored action sequence.
        """
        world = context.world  # bodies/poses below are resolved against it
        return sequential([
            ParkArmsAction(Arms.BOTH),
        ], context=context).plan


def main(execution_type: ExecutionType = ExecutionType.SIMULATED) -> None:
    """Run the demonstration.

    RobotDemonstration.run() acquires the world, starts the visualization backend,
    attaches the plan and performs it. The backend defaults to CRAMERA (the browser
    viewer); CORAPLEX_VISUALIZATION overrides it, so `cramera-live` works unchanged
    and you can also force RVIZ / NONE from the outside.

    :param execution_type: Whether to drive the real robot or simulate it.
    """
    MyDemoDemonstration(
        used_robot=UMe,
        execution_type=execution_type,
        collision_avoidance=True,
        default_visualization_backend=VisualizationBackend.CRAMERA,
    ).run()


if __name__ == "__main__":
    main()
